  const values = root.filter(v => v !== null);
  if (values.length > 100000) return 'The tree has at most 10^5 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Every node value is an integer between 1 and 10^6.';
