function isEvenOddTree(root) {
  let current = [root];
  let level = 0;

  while (current.length > 0) {
    const next = [];
    const evenLevel = level % 2 === 0;
    let prev = evenLevel ? 0 : Infinity;

    for (const node of current) {
      const val = node.val;
      if (evenLevel && (val % 2 === 0 || val <= prev)) {
        return false;
      }
      if (!evenLevel && (val % 2 === 1 || val >= prev)) {
        return false;
      }
      prev = val;
      if (node.left) {
        next.push(node.left);
      }
      if (node.right) {
        next.push(node.right);
      }
    }
    current = next;
    level++;
  }
  return true;
}

