function isEvenOddTree(root) {
  // Collect each level's values with a depth-first walk, then test every level on its own.
  const levels = [];
  const visit = (node, depth) => {
    if (!node) return;
    if (levels.length === depth) levels.push([]);
    levels[depth].push(node.val);
    visit(node.left, depth + 1);
    visit(node.right, depth + 1);
  };
  visit(root, 0);
  for (let depth = 0; depth < levels.length; depth++) {
    const vals = levels[depth];
    for (let i = 0; i < vals.length; i++) {
      if (depth % 2 === 0) {
        if (vals[i] % 2 !== 1) return false;
        if (i > 0 && !(vals[i - 1] < vals[i])) return false;
      } else {
        if (vals[i] % 2 !== 0) return false;
        if (i > 0 && !(vals[i - 1] > vals[i])) return false;
      }
    }
  }
  return true;
}

