function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 99) : 1 + Math.floor(rand() * 12);
  // Random shape: some trees start with a long chain, the rest grow by filling random free child slots.
  const nodes = [{ left: null, right: null }];
  const chain = large ? (rand() < 0.3 ? 50 + Math.floor(rand() * 200) : 1) : (rand() < 0.2 ? n : 1);
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Group node indices by level, left to right.
  const levels = [];
  let frontier = [0];
  while (frontier.length) {
    levels.push(frontier);
    const next = [];
    for (const i of frontier) {
      if (nodes[i].left !== null) next.push(nodes[i].left);
      if (nodes[i].right !== null) next.push(nodes[i].right);
    }
    frontier = next;
  }
  const mode = rand();
  if (!large && mode < 0.25) {
    // Fully random small values: mostly invalid trees with every kind of failure.
    for (const i of nodes.keys()) nodes[i].val = 1 + Math.floor(rand() * 10);
  } else {
    // Build a valid Even-Odd tree: odd increasing on even levels, even decreasing on odd levels.
    levels.forEach((ids, depth) => {
      const step = large ? Math.max(1, Math.floor(400000 / (ids.length + 1))) : 1 + Math.floor(rand() * 3);
      let v = (depth % 2 === 0 ? 1 : 2) + 2 * Math.floor(rand() * step);
      const vals = [];
      for (let j = 0; j < ids.length; j++) {
        vals.push(v);
        v += 2 * (1 + Math.floor(rand() * step));
      }
      if (depth % 2 === 1) vals.reverse();
      ids.forEach((id, j) => { nodes[id].val = vals[j]; });
    });
    // Half of the time break exactly one rule somewhere in the tree.
    if (rand() < 0.5) {
      const depth = Math.floor(rand() * levels.length);
      const ids = levels[depth];
      const j = Math.floor(rand() * ids.length);
      const kind = ids.length > 1 ? Math.floor(rand() * 3) : 0;
      const node = nodes[ids[j]];
      if (kind === 0) node.val = node.val % 2 === 1 ? (node.val < 1000000 ? node.val + 1 : node.val - 1) : node.val - 1;
      else if (kind === 1) node.val = nodes[ids[j === ids.length - 1 ? j - 1 : j + 1]].val;
      else {
        const other = nodes[ids[j === ids.length - 1 ? j - 1 : j + 1]];
        [node.val, other.val] = [other.val, node.val];
      }
    }
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
